/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-balance> - a level checked against the flows that should move it.
 *
 * For industrial,
 * terminal, aegis and antiseptic. A vessel's inventory taken from its LEVEL,
 * beside the same inventory taken from the integral of its METERED flows over
 * a declared window, with the residual judged against a tolerance built from
 * the instruments' own stated uncertainties - and with the level
 * transmitter's SPAN drawn on the vessel, so the part of the vessel no
 * transmitter can see is never mistaken for a part that is empty.
 *
 *   <ov-balance label="TANK 912" unit="bbl" level-unit="ft"
 *               height="170" capacity="42000" span-min="0" span-max="10"
 *               window="10800" meter-error="0.5" level-error="0.1"
 *               persist="60"></ov-balance>
 *   b.reading = {
 *     level: 7.9,
 *     in:  [{ id: 'FEED', rate: 20000 }],
 *     out: [{ id: 'LEVEL CONTROL VALVE', rate: 4100 }],
 *   };                                   // rates in `unit` per hour
 *
 * -- THE REFUSAL -----------------------------------------------------------
 *
 * 🔴 A LEVEL THE FLOWS CONTRADICT IS NOT A READING. It is LEVEL DISPUTED BY
 * FLOWS, and the element states the residual in both currencies: the volume
 * the meters say arrived, and the level change that volume should have
 * caused. This is the function the Buncefield investigators name as the one
 * that was missing (COMAH Competent Authority, "Buncefield: Why did it
 * happen?" p. 15): "Later versions of the ATG system had the ability to be set
 * to alarm in the event of inconsistencies between tank level measurements and
 * filling data, which would have provided a way of alerting control room staff
 * to an 'unexpected' static reading."
 *
 * And five that follow from it:
 *
 * 1. A MOVING WRONG LEVEL IS THE SAME STATE AS A STUCK ONE. There is no
 *    special flatline case here, because the second accident's level was
 *    MOVING. CSB, BP Texas City final report p. 54: "Unknown to the operators,
 *    the level of liquid in the tower at this time was 158 feet (nearly full),
 *    but the level transmitter reading had continued to decrease and now read
 *    78 percent (7.9 feet)". p. 79: the board operator "saw the declining
 *    level in the tower over three hours prior to the incident and believed
 *    the level was accurate, as he expected that the level would decline as
 *    the tower heated up". A falling level under net inflow is a dispute; so
 *    is a static one. `frozen` catches only the second, which is why this
 *    element exists.
 * 2. OUTSIDE THE TRANSMITTER'S SPAN THERE IS NO MEASUREMENT. The span is
 *    drawn on the vessel and the rest is hatched UNMEASURED, always, not only
 *    when the reading pegs. Texas City footnote 39: "The level transmitter
 *    output was expressed as a percentage of the transmitter's measurement
 *    span of approximately 5 feet in the bottom section of the column." A
 *    reading inside a span near the floor says nothing whatever about a tower
 *    158 feet full, and a display that draws only the span invites the reader
 *    to believe otherwise. When the flows put the contents above the span the
 *    element says EXPECTED ABOVE SPAN in as many words.
 * 3. AN UNKNOWN FLOW MEANS NOT CHECKED, NEVER CONFIRMED. One stream with no
 *    rate, or a meter declared failed, and the balance cannot be struck: the
 *    level is shown carrying the `unchecked` qualifier and the element names
 *    the stream it is missing. It never
 *    treats the streams it does have as a complete set.
 * 4. A WINDOW NOT YET FILLED IS NOT AGREEMENT. Until the element has watched
 *    for the whole declared window it says WINDOW NOT FILLED and how much of
 *    it it has. A balance struck over four seconds of history is not a balance.
 * 5. THE TOLERANCE IS THE INSTRUMENTS' OWN, DECLARED AND PRINTED. A residual
 *    is a dispute only beyond `meter-error` percent of the throughput that
 *    actually passed, plus the level transmitter's own `level-error`. Neither
 *    is defaulted: with either missing the element refuses to judge agreement
 *    at all. A dispute must also last `persist` seconds before it is called,
 *    and that persistence is PRINTED.
 *
 * No `role="img"` on the host: its children would become presentational and
 * the flow rows would never be read. The vessel drawing
 * is the only aria-hidden part; the two inventories, the residual and every
 * stream are real text.
 *
 * Drawn on each update and at most once a second while on screen, to advance
 * the integral and the persistence timer. Nothing runs every frame.
 *
 * Assumes a linear vessel (a real one needs a strapping table).
 * `disputed-by-flows` is not yet in ov-refusal.js's REASONS.
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';

const KEEP = 2;              // history kept, as a multiple of the window

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const num = (raw) => (raw === null || raw.trim() === '' ? null : Number(raw));
const finite = (v) => v !== null && Number.isFinite(v);
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

/* Volumes are read in thousands and must not lie about precision: no decimals
 * on a number that big, and always a thousands separator. */
const vol = (v) => (v === null || !Number.isFinite(v) ? '—'
  : (Math.abs(v) >= 100 ? Math.round(v) : Math.round(v * 10) / 10).toLocaleString('en-US'));
const signed = (v) => (v === null || !Number.isFinite(v) ? '—' : (v > 0 ? '+' : v < 0 ? '−' : '') + vol(Math.abs(v)));
const lvl = (v, places) => (v === null || !Number.isFinite(v) ? '—' : v.toFixed(places));
/* A level change is a LEVEL, not a volume: it keeps the level's decimals.
 * Passing it through vol() printed "+1 ft" for a foot and a hair. */
const signedLvl = (v, places) => (v === null || !Number.isFinite(v) ? '—'
  : (v > 0 ? '+' : v < 0 ? '\u2212' : '') + Math.abs(v).toFixed(places));
const dur = (s) => {
  const n = Math.max(0, Math.round(s));
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m ${String(n % 60).padStart(2, '0')}s`;
  return `${Math.floor(n / 3600)}h ${String(Math.floor((n % 3600) / 60)).padStart(2, '0')}m`;
};

let serial = 0;

export class OvBalance extends HTMLElement {
  static observedAttributes = ['src', 'label', 'unit', 'level-unit', 'height', 'capacity',
    'span-min', 'span-max', 'window', 'meter-error', 'level-error', 'persist', 'places', 'source'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._hist = [];        // { t, level, net, gross } - net and gross cumulative
    this._net = 0;          // cumulative metered volume in, minus out
    this._gross = 0;        // cumulative volume through every meter, for tolerance
    this._last = null;      // last sample time, for the integral
    this._streams = [];
    this._level = null;
    this._since = null;     // when the residual first went beyond tolerance
    this._malformed = 0;
    this._queue = [];
    this._said = '';
    this._uid = `ov-balance-${++serial}`;
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.evaluate();
    // The integral and the persistence timer both move without new readings.
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE. ov-core holds every feed, frame and
    // timer until the first screenful has landed, so the tick is started
    // through whenArrived rather than here; it fires at once on an element
    // upgraded after arrival, which is what lazy loading makes of this one.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.evaluate());
  }

  startTicking() {
    if (this._timer || !this.isConnected) return;
    this._timer = setInterval(() => { if (isSeen(this)) this.sample(); }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.evaluate();
  }

  /* A scene from a file, so the element renders as plain markup on a page that
   * carries no script: `<ov-balance src="models/balance-x.json">`. The same
   * route the kit's other data-driven elements take (ov-consistency,
   * ov-coverage), and the reason a reference page can show one at all.
   *
   * 🔴 A FETCH THAT FAILS LEAVES NO SCENE, NOT A STALE ONE. The element then
   * says what it says with no data, which is its own refusal rather than the
   * last thing that happened to load. The src check after the await is for a
   * src changed while the request was in flight: the loser must not win.
   */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch {
      data = null;
    }
    if (this.getAttribute('src') !== src) return;
    this.reading = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (x) => { this.reading = x; });
  }

  /* ---- taking readings in ----------------------------------------------- */

  set reading(r) {
    /* 🔴 MOVEMENT IS A PROPERTY OF THE READING, NOT OF THE REPAINT. replay()
     * walks a whole window and paints once per sample, so asking "did the
     * level change since the last paint" compared the final sample with
     * itself and always answered no. The question is whether this READING
     * differs from the one before it, so it is asked here, once. */
    const before = this._level;
    if (r && typeof r === 'object' && Array.isArray(r.samples)) this.replay(r.samples);
    else this.take(r);
    this._moving = before !== null && before !== undefined && this._level !== null
      && Math.abs(this._level - before) > 1e-9;
    this.evaluate();
  }

  /* Replay stated samples, each carrying its own age in seconds, oldest
   * first. 🔴 THIS IS NOT A SHORTCUT PAST THE ARITHMETIC: every sample goes
   * through the same integral step as a live reading, at its own instant, so
   * a seeded balance and a watched one reach the same residual by the same
   * route. Seeding `_hist` directly would be a second way to compute the
   * thing this element exists to compute. */
  replay(samples) {
    this._hist = [];
    this._net = 0;
    this._gross = 0;
    this._last = null;
    this._since = null;
    const now = OvBalance.now();
    const list = (samples || [])
      .filter((x) => x && typeof x === 'object' && Number.isFinite(Number(x.ago)))
      .sort((a, b) => Number(b.ago) - Number(a.ago));
    for (const x of list) this.take(x, now - Number(x.ago) * 1000);
    this.evaluate();
  }

  take(r, at) {
    if (!r || typeof r !== 'object') { this._malformed++; this.evaluate(); return; }
    const level = r.level === null || r.level === undefined ? null : Number(r.level);
    this._level = Number.isFinite(level) ? level : null;
    const take = (list, dir) => (Array.isArray(list) ? list : []).map((s) => {
      if (!s || typeof s !== 'object' || s.id === undefined) { this._malformed++; return null; }
      const rate = s.rate === null || s.rate === undefined ? null : Number(s.rate);
      return {
        id: String(s.id),
        dir,
        // A failed meter is not a rate of zero. Zero is a reading.
        rate: s.status === 'failed' || !Number.isFinite(rate) ? null : rate,
        status: s.status === 'failed' ? 'failed' : Number.isFinite(rate) ? 'reading' : 'unknown',
      };
    }).filter(Boolean);
    this._streams = [...take(r.in, 'in'), ...take(r.out, 'out')];
    this.sample(at);
  }

  get reading() { return { level: this._level, streams: this._streams }; }

  /* One step of the integral. Called on every reading and once a second, so a
   * rate that stands still still moves the balance. */
  sample(at) {
    const now = at === undefined ? OvBalance.now() : at;
    const known = this._streams.every((s) => s.rate !== null);
    if (this._last !== null && known) {
      const hours = (now - this._last) / 3_600_000;
      if (hours > 0) {
        let net = 0;
        let gross = 0;
        for (const s of this._streams) {
          net += (s.dir === 'in' ? 1 : -1) * s.rate * hours;
          gross += Math.abs(s.rate) * hours;
        }
        this._net += net;
        this._gross += gross;
      }
    }
    this._last = now;
    if (this._level !== null) {
      this._hist.push({ t: now, level: this._level, net: this._net, gross: this._gross });
      const win = num(this.getAttribute('window'));
      const keep = (finite(win) && win > 0 ? win : 600) * KEEP * 1000;
      while (this._hist.length > 2 && now - this._hist[0].t > keep) this._hist.shift();
    }
    this.evaluate();
  }

  /* ---- striking the balance --------------------------------------------- */

  evaluate() {
    if (!this._built) return this._report;
    const now = OvBalance.now();
    const p = {
      height: num(this.getAttribute('height')),
      capacity: num(this.getAttribute('capacity')),
      spanMin: num(this.getAttribute('span-min')),
      spanMax: num(this.getAttribute('span-max')),
      window: num(this.getAttribute('window')),
      meterError: num(this.getAttribute('meter-error')),
      levelError: num(this.getAttribute('level-error')),
      persist: num(this.getAttribute('persist')),
    };
    const r = {
      state: 'empty', level: this._level, invLevel: null, invMeters: null,
      residual: null, tol: null, expected: null, aboveSpan: false, inSpan: null,
      unknown: [], covered: 0, held: 0, why: '', windowHave: 0,
    };
    const done = () => { this._report = r; this.paint(r, p); this.announce(r); return r; };

    // The vessel itself must be declared: without height and capacity a level
    // cannot become an inventory at all.
    if (!finite(p.height) || p.height <= 0 || !finite(p.capacity) || p.capacity <= 0) {
      r.state = 'undeclared';
      r.why = 'VESSEL NOT DECLARED · height and capacity are required';
      return done();
    }
    const perLevel = p.capacity / p.height;

    if (this._level === null) {
      r.state = 'nolevel';
      r.why = 'NO LEVEL';
      return done();
    }
    r.invLevel = this._level * perLevel;

    // Refusal 2: the span is where the transmitter can see, and it is drawn
    // whether or not the reading is inside it.
    if (finite(p.spanMin) && finite(p.spanMax) && p.spanMax > p.spanMin) {
      r.inSpan = this._level >= p.spanMin && this._level <= p.spanMax;
      r.covered = (p.spanMax - p.spanMin) / p.height;
    }

    // Refusal 5: neither uncertainty is defaulted.
    if (!finite(p.meterError) || p.meterError < 0 || !finite(p.levelError) || p.levelError < 0) {
      r.state = 'unruled';
      r.why = 'NO TOLERANCE DECLARED · meter-error and level-error are required';
      return done();
    }
    // Refusal 3: a stream with no rate stops the check.
    r.unknown = this._streams.filter((s) => s.rate === null).map((s) => s.id);
    if (r.unknown.length) {
      r.state = 'unchecked';
      r.why = `NOT CHECKED · no rate from ${r.unknown.join(', ')}`;
      this._since = null;
      return done();
    }
    if (!this._streams.length) {
      r.state = 'unchecked';
      r.why = 'NOT CHECKED · no metered stream declared';
      this._since = null;
      return done();
    }

    const win = finite(p.window) && p.window > 0 ? p.window : null;
    if (win === null) {
      r.state = 'unruled';
      r.why = 'NO WINDOW DECLARED · the balance has no period to be struck over';
      return done();
    }

    // The sample at the start of the window, and how much window we have.
    const head = this._hist[0];
    const tail = this._hist[this._hist.length - 1];
    if (!head || !tail || head === tail) {
      r.state = 'short';
      r.why = `WINDOW NOT FILLED · ${dur(0)} of ${dur(win)}`;
      return done();
    }
    // Two durations, and they are not the same thing: `have` is how much
    // history exists, which decides whether the window is filled; `span` is
    // the period actually measured over, which is what the residual is a
    // residual FOR. Stating a windowed volume against the whole of history
    // would be a sentence whose two halves disagree.
    r.windowHave = (tail.t - head.t) / 1000;
    const want = now - win * 1000;
    const start = this._hist.find((h) => h.t >= want) || head;
    r.span = (tail.t - start.t) / 1000;

    // Refusal 4: a window not yet filled is not agreement.
    if (r.windowHave < win) {
      r.state = 'short';
      r.why = `WINDOW NOT FILLED · ${dur(r.windowHave)} of ${dur(win)}`;
      this._since = null;
      return done();
    }

    const dNet = tail.net - start.net;
    const dGross = tail.gross - start.gross;
    r.invMeters = start.level * perLevel + dNet;
    r.expected = start.level + dNet / perLevel;
    r.residual = r.invLevel - r.invMeters;     // what the level is missing
    r.tol = (p.meterError / 100) * Math.abs(dGross) + p.levelError * perLevel;
    r.dNet = dNet;
    r.dLevel = tail.level - start.level;
    r.over = Math.abs(r.residual) > r.tol && Math.abs(r.dLevel) < 1e-9;  // MUTANT: only a stuck level counts
    r.aboveSpan = finite(p.spanMax) && r.expected > p.spanMax;

    if (!r.over) {
      this._since = null;
      r.state = 'agrees';
      r.why = `LEVEL AND FLOWS AGREE within ±${vol(r.tol)} ${this.unit()}`;
      return done();
    }
    // The dispute must last `persist` seconds before it is called one.
    const persist = finite(p.persist) && p.persist > 0 ? p.persist : 0;
    if (this._since === null) this._since = now;
    r.held = (now - this._since) / 1000;
    if (r.held < persist) {
      r.state = 'watching';
      r.why = `RESIDUAL BEYOND TOLERANCE FOR ${dur(r.held)} OF ${dur(persist)}`;
      return done();
    }
    r.state = 'disputed';
    // 🔴 The residual in both currencies: the volume, and the level change it
    // should have caused against the one that happened. A level that did not
    // move says so in those words - the Buncefield report's "unexpected"
    // static reading - rather than "rose 0.0", which reads as a movement.
    const moved = lvl(Math.abs(r.dLevel), this.places());
    const moveText = Number(moved) === 0
      ? 'level DID NOT MOVE'
      : `level ${r.dLevel > 0 ? 'rose' : 'fell'} ${moved} ${this.levelUnit()}`;
    r.why = `${signed(r.dNet)} ${this.unit()} metered over ${dur(r.span)}, `
      + `${moveText} where ${signedLvl(dNet / perLevel, this.places())} ${this.levelUnit()} was due`;
    return done();
  }

  get report() { return this._report; }

  unit() { return this.getAttribute('unit') || 'units'; }
  levelUnit() { return this.getAttribute('level-unit') || 'm'; }
  label() { return this.getAttribute('label') || 'BALANCE'; }
  places() {
    const p = num(this.getAttribute('places'));
    return finite(p) && p >= 0 && p <= 4 ? Math.floor(p) : 1;
  }

  /* Announcements from one update are JOINED into one: several writes to a
   * live region in one task are heard as the last only (d7c18ae). */
  say(text) {
    this._queue.push(text);
    if (this._flushing) return;
    this._flushing = true;
    queueMicrotask(() => {
      this._flushing = false;
      const t = this._queue.join('; ');
      this._queue = [];
      const region = this.querySelector('.ov-balance__say');
      if (region) { region.textContent = ''; region.textContent = t; }
    });
  }

  /* Only a CHANGE of standing is spoken. A residual creeping up is not news
   * every second; crossing into dispute is. */
  announce(r) {
    const key = `${r.state}|${r.unknown.join(',')}`;
    if (key === this._said) return;
    const first = this._said === '';
    this._said = key;
    if (first) return;
    if (r.state === 'disputed') this.say(`${this.label()}: level disputed by flows, ${r.why.toLowerCase()}`);
    else if (r.state === 'unchecked') this.say(`${this.label()}: ${r.why.toLowerCase()}`);
    else if (r.state === 'agrees') this.say(`${this.label()}: level and flows agree again`);
  }

  /* ---- drawing ---------------------------------------------------------- */

  build() {
    this._built = true;
    this.innerHTML = `
      <div class="ov-state ov-state--bar ov-balance__verdict">
        <span class="ov-aside ov-balance__label"></span>
        <span class="ov-balance__word"></span>
        <span class="ov-aside ov-balance__why"></span>
      </div>
      <div class="ov-balance__body">
        <div class="ov-balance__vessel" aria-hidden="true">
          <div class="ov-balance__shell">
            <div class="ov-balance__unmeasured ov-balance__unmeasured--hi"></div>
            <div class="ov-balance__unmeasured ov-balance__unmeasured--lo"></div>
            <div class="ov-balance__span"></div>
            <div class="ov-balance__fill"></div>
            <div class="ov-balance__gap"></div>
            <div class="ov-balance__mark ov-balance__mark--level"><b></b></div>
            <div class="ov-balance__mark ov-balance__mark--exp"><b></b></div>
          </div>
          <div class="ov-aside ov-balance__spanlabel"></div>
        </div>
        <dl class="ov-balance__sums">
          <div><dt>LEVEL SAYS</dt><dd class="ov-balance__fromlevel"></dd></div>
          <div><dt>METERS SAY</dt><dd class="ov-balance__frommeters"></dd></div>
          <div><dt>RESIDUAL</dt><dd class="ov-balance__residual"></dd></div>
        </dl>
      </div>
      <ol class="ov-balance__streams"></ol>
      <div class="ov-aside ov-balance__rulebox"></div>
      <div class="ov-balance__foot"></div>
      <div class="ov-balance__say" aria-live="polite"></div>`;
    this.setAttribute('role', 'group');
  }

  paint(r, p) {
    const q = (s) => this.querySelector(s);
    const U = this.places();
    setText(q('.ov-balance__label'), this.label());
    const tolText = finite(p.meterError) && finite(p.levelError)
      ? `±${p.meterError}% + ±${p.levelError} ${this.levelUnit()}`
      : 'NO TOLERANCE';
    setText(q('.ov-balance__rulebox'),
      `OVER ${finite(p.window) && p.window > 0 ? dur(p.window) : 'NO WINDOW'} · ${tolText}`
      + (finite(p.persist) && p.persist > 0 ? ` · HELD ${dur(p.persist)}` : ''));

    setAttr(this, 'data-ov-state', r.state);
    setAttr(q('.ov-balance__verdict'), 'data-ov-tone',
      r.state === 'agrees' ? 'ok'
        : r.state === 'watching' || r.state === 'unchecked' || r.state === 'short' ? 'note' : 'bad');
    const WORD = {
      agrees: 'LEVEL AGREES WITH FLOWS',
      disputed: 'LEVEL DISPUTED BY FLOWS',
      watching: 'CHECKING',
      unchecked: 'NOT CHECKED',
      short: 'NOT CHECKED',
      unruled: 'CANNOT CHECK',
      undeclared: 'CANNOT CHECK',
      nolevel: 'NO LEVEL',
      empty: 'NO READING',
    };
    setText(q('.ov-balance__word'), WORD[r.state] || r.state);
    setText(q('.ov-balance__why'), r.why);

    // A disputed level is a refusal; an unchecked one keeps its number and
    // carries the ruled `unchecked` qualifier.
    setAttr(this, 'data-ov-refusal',
      r.state === 'disputed' ? 'disputed-by-flows'
        : r.state === 'nolevel' ? 'unknown'
          : r.state === 'undeclared' || r.state === 'empty' ? 'unknown' : null);
    setAttr(this, 'data-ov-qualified',
      r.state === 'unchecked' || r.state === 'short' || r.state === 'unruled' ? 'unchecked' : null);
    setAttr(this, 'data-ov-refusal-text', r.state === 'disputed' ? 'level disputed by flows' : null);

    setText(q('.ov-balance__fromlevel'), r.invLevel === null ? '—'
      : `${vol(r.invLevel)} ${this.unit()}  ·  ${lvl(r.level, U)} ${this.levelUnit()}`);
    const showMeters = r.invMeters !== null;
    setText(q('.ov-balance__frommeters'), !showMeters ? '—'
      : `${vol(r.invMeters)} ${this.unit()}  ·  ${lvl(r.expected, U)} ${this.levelUnit()}`
        + (r.aboveSpan ? '  ·  ABOVE SPAN' : ''));
    setText(q('.ov-balance__residual'), r.residual === null ? '—'
      : `${signed(r.residual)} ${this.unit()}  ·  TOLERANCE ±${vol(r.tol)}`);
    setAttr(q('.ov-balance__residual'), 'data-ov-over', r.over ? '' : null);
    setAttr(q('.ov-balance__frommeters'), 'data-ov-above', r.aboveSpan ? '' : null);

    this.setAttribute('aria-label', r.state === 'disputed'
      ? `${this.label()}: level disputed by flows. ${r.why}`
      : r.state === 'agrees'
        ? `${this.label()}: level ${lvl(r.level, U)} ${this.levelUnit()}, agreeing with the flows within ${vol(r.tol)} ${this.unit()}`
        : `${this.label()}: ${(WORD[r.state] || r.state).toLowerCase()}. ${r.why}`);

    this.paintVessel(r, p);
    this.paintStreams(r);

    setText(q('.ov-balance__foot'), this._malformed
      ? `${this._malformed} malformed reading${this._malformed > 1 ? 's' : ''} ignored` : '');
  }

  paintVessel(r, p) {
    const q = (s) => this.querySelector(s);
    const shell = q('.ov-balance__shell');
    const ok = finite(p.height) && p.height > 0;
    setAttr(shell, 'data-ov-undeclared', ok ? null : '');
    if (!ok) {
      for (const s of ['.ov-balance__fill', '.ov-balance__gap', '.ov-balance__span',
        '.ov-balance__unmeasured--hi', '.ov-balance__unmeasured--lo']) q(s).style.cssText = '';
      q('.ov-balance__mark--level').hidden = true;
      q('.ov-balance__mark--exp').hidden = true;
      setText(q('.ov-balance__spanlabel'), '');
      return;
    }
    const pct = (v) => `${clamp((v / p.height) * 100, 0, 100)}%`;
    // A label centred on the line falls half outside the shell at the floor
    // and the roof, so near either end it moves wholly clear of the line.
    const place = (v) => {
      const at = clamp((v / p.height) * 100, 0, 100);
      return at < 9 ? 'above' : at > 91 ? 'below' : 'on';
    };
    const U = this.places();

    // 🔴 The span, and everything outside it, drawn as a permanent fact about
    // this instrument rather than a state it is in.
    const hasSpan = finite(p.spanMin) && finite(p.spanMax) && p.spanMax > p.spanMin;
    q('.ov-balance__span').style.cssText = hasSpan
      ? `bottom:${pct(p.spanMin)};height:${clamp(((p.spanMax - p.spanMin) / p.height) * 100, 0, 100)}%` : '';
    q('.ov-balance__unmeasured--hi').style.cssText = hasSpan
      ? `bottom:${pct(p.spanMax)};top:0` : 'display:none';
    q('.ov-balance__unmeasured--lo').style.cssText = hasSpan && p.spanMin > 0
      ? `bottom:0;height:${pct(p.spanMin)}` : 'display:none';
    setText(q('.ov-balance__spanlabel'), hasSpan
      ? `TRANSMITTER SEES ${lvl(p.spanMin, U)}–${lvl(p.spanMax, U)} ${this.levelUnit()} OF ${lvl(p.height, U)} · ${Math.round(r.covered * 100)}% OF THE VESSEL`
      : `NO SPAN DECLARED · ${lvl(p.height, U)} ${this.levelUnit()} VESSEL`);

    const level = r.level;
    q('.ov-balance__fill').style.cssText = level === null ? 'display:none' : `height:${pct(level)}`;

    /* 🔴 THE SURFACE MOVES ONLY WHILE THE LEVEL DOES, and that is the rule the
     * decoration has to earn. A tank drawn with a permanently shimmering
     * surface says "liquid"; one whose surface goes DEAD STILL the moment the
     * reading stops changing says "this gauge has stopped", which is the fault
     * this element exists to catch. So stillness is a reading here, not a
     * default, and a stuck transmitter is visible before a word is read.
     *
     * ⚠️ Compared against the LAST DRAWN level rather than a velocity: the
     * element is told levels, not rates, and a rate it computed itself would
     * be a number the instrument never sent. */
    setAttr(this, 'data-ov-moving', this._moving ? '' : null);

    const markLevel = q('.ov-balance__mark--level');
    markLevel.hidden = level === null;
    if (level !== null) {
      markLevel.style.bottom = pct(level);
      setAttr(markLevel, 'data-ov-place', place(level));
      setText(markLevel.querySelector('b'), `LEVEL ${lvl(level, U)}`);
      setAttr(markLevel, 'data-ov-outside', hasSpan && !r.inSpan ? '' : null);
    }

    // The expected level, pinned at the top when the flows put the contents
    // above the vessel's own shell - which is itself the finding.
    const markExp = q('.ov-balance__mark--exp');
    const exp = r.expected;
    const showExp = exp !== null && exp !== undefined && Number.isFinite(exp) && (r.state === 'disputed' || r.state === 'watching' || r.state === 'agrees');
    markExp.hidden = !showExp;
    if (showExp) {
      const over = exp > p.height;
      markExp.style.bottom = pct(exp);
      setAttr(markExp, 'data-ov-pinned', over ? '' : null);
      setAttr(markExp, 'data-ov-place', place(clamp(exp, 0, p.height)));
      // The label stays short: ABOVE SPAN has its own place on the METERS SAY
      // line and in the verdict, and repeating it here made a label long
      // enough for the shell to clip.
      setText(markExp.querySelector('b'), `FLOWS ${lvl(exp, U)}${over ? ' \u2191' : ''}`);
    }

    // The residual, as the distance between the two marks.
    const gap = q('.ov-balance__gap');
    if (showExp && level !== null && r.over) {
      const lo = Math.min(level, clamp(exp, 0, p.height));
      const hi = Math.max(level, clamp(exp, 0, p.height));
      gap.style.cssText = `bottom:${pct(lo)};height:${clamp(((hi - lo) / p.height) * 100, 0, 100)}%`;
      gap.hidden = false;
    } else {
      gap.hidden = true;
    }
  }

  paintStreams(r) {
    const list = this.querySelector('.ov-balance__streams');
    const key = this._streams.map((s) => s.dir + s.id).join('|');
    if (this._streamKey !== key) {
      this._streamKey = key;
      list.innerHTML = this._streams.map((s) => `
        <li class="ov-balance__stream" data-ov-stream="${esc(s.id)}" data-ov-dir="${s.dir}">
          <span class="ov-balance__arrow" aria-hidden="true">${s.dir === 'in' ? '→' : '→'}</span>
          <span class="ov-balance__dir">${s.dir === 'in' ? 'IN' : 'OUT'}</span>
          <span class="ov-balance__sid">${esc(s.id)}</span>
          <span class="ov-balance__rate"></span>
          <span class="ov-balance__sword"></span>
        </li>`).join('');
    }
    this._streams.forEach((s, i) => {
      const li = list.children[i];
      if (!li) return;
      setAttr(li, 'data-ov-status', s.status);
      setText(li.querySelector('.ov-balance__rate'), s.rate === null ? '—' : `${vol(s.rate)} ${this.unit()}/h`);
      setText(li.querySelector('.ov-balance__sword'),
        s.status === 'failed' ? 'METER FAILED' : s.status === 'unknown' ? 'NO RATE' : s.rate === 0 ? 'READING ZERO' : '');
    });
    setAttr(list, 'hidden', this._streams.length ? null : '');
  }
}

define('ov-balance', OvBalance);
